"""Single host-gated path combining Version 1 *contextual* retrieval and truth ledger.

Untrusted societal knowledge suggests questions only. The only output that
can reach a user is generated by the original GovernedModelBridge renderer.
"""
from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from typing import Any, Protocol

from .bridge import GovernedModelBridge, GatedResponse
from .governed import GovernedTruthCore
from .societal_v1 import Version1ReadOnlyAdapter, ContextCandidate
from .version1_runtime import Version1RuntimeAdvisor
from .semantic import semantic_warnings
from .governed import _unique_pairs, _reject_constant


class Proposer(Protocol):
    def generate_proposal(self, source_id: str, source_text: str, *,
                          contextual_references: list[dict] | None = None) -> str: ...


@dataclass(frozen=True)
class SocietalGatedResult:
    source_id: str
    context_refs: tuple[str, ...]
    context_status: str
    decision: str
    response: str
    raw_proposal_sha256: str | None
    claim_id: str | None
    established_fact: bool
    version1_runtime_review: str = "NOT_ATTACHED"


class SocietalGatedPipeline:
    """A single host-operated entrypoint. Never expose a raw LLM output route."""

    def __init__(self, core: GovernedTruthCore, bridge: GovernedModelBridge,
                 contextual_adapter: Version1ReadOnlyAdapter | None = None,
                 runtime_advisor: Version1RuntimeAdvisor | None = None):
        if bridge.core is not core:
            raise ValueError("The bridge must use the same canonical truth core")
        if contextual_adapter is not None and contextual_adapter.last_inspection is None:
            raise ValueError("Context adapter must have passed source inspection")
        self.core = core
        self.bridge = bridge
        self.contextual_adapter = contextual_adapter
        if runtime_advisor is not None and (contextual_adapter is None or
                contextual_adapter.mapping is None or
                contextual_adapter.last_inspection.status != "MAPPED_2000_RECORDS_SOURCE_ONLY"):
            raise ValueError("A verified 2,000-entry read-only source binding is required")
        self.runtime_advisor = runtime_advisor

    def execute(self, *, speaker_id: str, exact_text: str, proposer: Proposer,
                trusted_scope: dict | None = None) -> SocietalGatedResult:
        if not speaker_id or not isinstance(exact_text, str) or not exact_text:
            raise ValueError("Identified speaker and nonempty exact text required")
        if trusted_scope is not None and not isinstance(trusted_scope, dict):
            raise ValueError("Host scope must be an object")
        source_id = self.core.preserve(speaker_id, exact_text)
        contexts: tuple[ContextCandidate,...] = ()
        context_status = "NO_VERSION1_SOURCE_ATTACHED"
        if self.contextual_adapter is not None:
            contexts = self.contextual_adapter.candidates(exact_text, limit=4)
            context_status = ("ADVISORY_CONTEXT_CANDIDATES_ONLY" if contexts
                              else "NO_MATCHING_CONTEXT_FOUND")
        # The host alone supplies claim scope. Context IDs must not be promoted
        # to evidence references by the model or by this wrapper.
        scope = dict(trusted_scope or {})
        scope["societal_context_refs"] = [
            {"entry_id": x.entry_id, "record_digest": x.text_sha256,
             "source_member": x.source_member, "line": x.line,
             "authority": "UNVERIFIED_CONTEXT_ONLY"} for x in contexts
        ]
        ctx_payload = [
            {"id": x.entry_id, "text": x.exact_text[:1024],
             "status": "UNTRUSTED_CONTEXT_NOT_PERSON_EVIDENCE"} for x in contexts
        ]
        raw = proposer.generate_proposal(source_id, exact_text, contextual_references=ctx_payload)
        if not isinstance(raw,str):
            raise TypeError("Model returned non-text proposal")
        # Do not run a JSON parser on an unbounded provider response.
        if len(raw)>32768:
            raise ValueError("Proposer output exceeds the 32 KiB contract")
        raw_bytes=raw.encode('utf-8')
        if len(raw_bytes)>32768:
            raise ValueError("Proposer output exceeds the 32 KiB contract")
        raw_digest = hashlib.sha256(raw_bytes).hexdigest()
        # Do not let a speculative person/intent attribution escape merely by
        # using 'hypothesis' rather than 'paraphrase'. This is only a limited
        # known-risk heuristic, not general semantic understanding.
        try:
            candidate = json.loads(raw,object_pairs_hook=_unique_pairs,
                                   parse_constant=_reject_constant)
        except (ValueError,TypeError,json.JSONDecodeError):
            candidate = None
        if (isinstance(candidate,dict) and candidate.get('kind')=='hypothesis'
            and isinstance(candidate.get('text'),str)
            and 'POSSIBLE_UNSTATED_MENTAL_STATE' in semantic_warnings(exact_text,candidate['text'])):
            return SocietalGatedResult(source_id,tuple(x.entry_id for x in contexts),
                context_status,"NEEDS_PERSON_EVIDENCE",
                "A proposed interpretation about a person's internal state lacks source support and was not published.",
                raw_digest,None,False)
        try:
            gated: GatedResponse = self.bridge.process(raw,
                            current_source_id=source_id, trusted_scope=scope)
        except (ValueError,TypeError,PermissionError,json.JSONDecodeError):
            return SocietalGatedResult(source_id,tuple(x.entry_id for x in contexts),
                context_status,"MODEL_PROPOSAL_REJECTED",
                "The proposed interpretation was rejected. The original statement was preserved without endorsing new claims.",
                raw_digest,None,False)
        review_status = "NOT_ATTACHED"
        if self.runtime_advisor is not None:
            try:
                report = self.runtime_advisor.review(speaker_id=speaker_id,
                    source_id=source_id, exact_text=exact_text, gated_draft=gated.text)
            except (ValueError, TypeError, RuntimeError, KeyError):
                return SocietalGatedResult(source_id,tuple(x.entry_id for x in contexts),
                    context_status,"VERSION1_REVIEW_FAILURE",
                    "The supplementary Version 1 review failed; no model output was published.",
                    raw_digest,gated.claim_id,False,"REVIEW_FAILURE")
            review_status = report.status
            if report.status != "ADVISORY_PASS":
                return SocietalGatedResult(source_id,tuple(x.entry_id for x in contexts),
                    context_status,"VERSION1_REVIEW_HOLD",
                    "A supplementary source-based review requires a human assessment; "
                    "the proposed response was withheld.",raw_digest,gated.claim_id,
                    False,report.status)
        return SocietalGatedResult(source_id,tuple(x.entry_id for x in contexts),
                         context_status,gated.decision,gated.text,raw_digest,
                         gated.claim_id,gated.established_fact,review_status)
